  "The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.": "ردیف مشخص‌شده، محدوده معمول بیشتر ست‌های اصلی است. ست‌های قبلی مقیاس خود را حفظ می‌کنند و این مقدار روی پیشرفت یا 1RM تخمینی تأثیری ندارد.",
