  "Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.": "سرور شما مربی را با ارائه‌دهنده‌ای که مدیر تنظیم کرده اجرا می‌کند. اطلاعاتی فراتر از داده‌هایی که از قبل همگام می‌شوند، از این گوشی ارسال نمی‌شود.",
