  "Top sets logged without an effort rating; add RIR so the next review can read how hard they were.": "ست‌های برتر بدون شدت ثبت شده‌اند؛ RIR را اضافه کنید تا در بررسی بعدی میزان سختی آن‌ها مشخص باشد.",
