  "Muscle map": "نقشه عضلانی",
  "Show which muscles this workout trained.": "نشان دهید که این تمرین کدام عضلات را تمرین داده است.",
  "Preview of the image to share": "پیش نمایش تصویر برای اشتراک گذاری",
