  "Its workouts do not count toward progression. They still show in history and statistics.": "تمرینات آن برای پیشرفت به حساب نمی‌آید. هنوز در تاریخ و آمار نشان می‌دهند.",
  "A deload routine opens at the numbers set here, so the progression above does not apply to it.": "روتین کاهش بار با مقادیر تعیین‌شده در اینجا شروع می‌شود؛ بنابراین قانون پیشرفت بالا روی آن اعمال نمی‌شود.",
  "Replace exercise": "تمرین را جایگزین کنید",
