  "Add a sign-in e-mail": "افزودن ایمیل ورود",
  "Type it at “Sign in with password” instead of your profile name. We never send anything to it; a forgotten password is still reset by your admin.": "آن را به جای نام پروفایل خود در «ورود با رمز عبور» تایپ کنید. ما هرگز چیزی به آن نمی‌فرستیم. رمز عبور فراموش شده هنوز توسط سرپرست شما بازنشانی می‌شود.",
