  "Could not reach {0}. Check the address and that this phone can reach it.": "اتصال به {0} برقرار نشد. نشانی و دسترسی این گوشی به سرور را بررسی کنید.",
  "The end of a rest or a hold buzzes like an alarm, even in silent mode.": "پایان استراحت یا نگه داشتن، حتی در حالت بی‌صدا، مانند زنگ هشدار به صدا در می‌آید.",
