  "Off: the bar at the top is hidden. A dot on Home still warns when syncing is stuck.": "خاموش: نوار در بالا پنهان است. هنگامی که همگام‌سازی متوقف می‌شود، یک نقطه در صفحه اصلی همچنان هشدار می‌دهد.",
