  "The barbell asked about you today. I didn’t know what to say.": "هالتر امروز سراغت رو گرفت. نمی‌دونستم چی بگم.",
  "Was it something I said? {0} misses you.": "چیزی گفتم ناراحت شدی؟ {0} دلتنگته.",
  "I saved you a spot on the bench. It’s still empty.": "یه جا روی نیمکت برات نگه داشتم. هنوز خالیه.",
  "Attention, recruit!": "خبردار، سرباز!",
  "Your gains are packing their bags. {0} tomorrow, no excuses!": "عضله‌هات دارن چمدون می‌بندن. فردا {0}، بدون بهانه!",
