  "Your muscles filed a missing-person report. Show up for {0}!": "عضله‌هات اعلام مفقودی کردن. برای {0} خودت رو برسون!",
  "That address answers, but it isn’t an openGym server. Check the URL.": "نشانی در دسترس است، اما متعلق به سرور openGym نیست. نشانی اینترنتی (URL) را بررسی کنید.",
  "That address answers, but a login page or proxy rule replied instead of openGym. Let /api/ through to openGym unchanged. See “Phone app and CORS” in docs/SELF_HOSTING.md.": "آن آدرس پاسخ می‌دهد، اما یک صفحه ورود یا قانون پروکسی به جای openGym پاسخ داده است. اجازه دهید /api/ بدون تغییر به openGym برود. به «برنامه تلفن و CORS» در docs/SELF_HOSTING.md مراجعه کنید.",
  "Switch sides": "عوض کردن طرف",
  "Saves a dated copy to “{0}” after finishing a workout or editing a routine, and keeps the newest {1}.": "پس از پایان تمرین یا ویرایش یک روتین، یک کپی تاریخ را در \"{0}\" ذخیره می‌کند و جدیدترین {1} را نگه می‌دارد.",
