  "To answer, the Coach sends this through your openGym server to {0}, an AI service outside openGym that your server’s admin picked:": "برای پاسخ، مربی این را از طریق سرور openGym شما به {0} می‌فرستد، یک سرویس هوش مصنوعی خارج از openGym که سرپرست سرور شما انتخاب کرده است:",
  "To answer, this device sends this straight to {0}, an AI service outside openGym, with your API key:": "برای پاسخ، این دستگاه این را مستقیماً به {0}، یک سرویس هوش مصنوعی خارج از openGym، با کلید API شما ارسال می‌کند:",
  "Who may see your training": "چه کسی ممکن است اطلاعات تمرین‌هایتان را ببیند",
  "Who the Coach may send your training to from this device. Withdraw it and the Coach asks again next time. A model on your own network never needs asking.": "سرویسی که مربی اجازه دارد اطلاعات تمرین شما را از این دستگاه برای آن ارسال کند. با لغو مجوز، مربی دفعه بعد دوباره اجازه می‌گیرد. برای استفاده از مدلی در شبکه خودتان نیازی به دریافت مجوز نیست.",
  "With your API key": "با کلید API شما",
