  "Slower than planned": "کندتر از برنامه‌ریزی شده",
  "Gaining faster than planned": "افزایش وزن سریع‌تر از برنامه",
  "Losing faster than planned": "کاهش وزن سریع‌تر از برنامه",
  "Outside your range": "خارج از محدوده شما",
  "Enter a range first": "ابتدا یک محدوده را وارد کنید",
  "The trend through your weigh-ins of the last 3 weeks, so one salty dinner does not move it. Give it a range and the card tells you whether you are on pace.": "روند وزن‌کشی‌های 3 هفته گذشته، تا یک شام شور آن را تغییر ندهد. بازه هدف را تعیین کنید تا کارت نشان دهد مطابق برنامه پیش می‌روید یا نه.",
  "Lose": "کاهش وزن",
