  "Within ±": "در ±",
  "Hold within ±{0} a week.": "حفظ وزن در محدوده ±{0} در هفته.",
  "Lose {0} to {1} a week.": "کاهش وزن {0} تا {1} در هفته.",
  "Gain {0} to {1} a week.": "افزایش وزن {0} تا {1} در هفته.",
  "A cut is often 0.5 to 1 % a week, a lean bulk 0.25 to 0.5 %.": "در دوره کاهش چربی معمولاً 0.5 تا 1٪ در هفته و در دوره افزایش حجم کم‌چربی 0.25 تا 0.5٪ در هفته هدف‌گذاری می‌شود.",
  "Remove range": "محدوده را بردارید",
  "Admin": "مدیر",
  "Heaviest set as a share of body weight, per workout": "سنگین‌ترین ست به عنوان سهم وزن بدن، در هر تمرین",
  "Estimated 1RM as a share of body weight, per workout": "1RM به عنوان سهمی از وزن بدن در هر تمرین تخمین زده شده است",
  "Body weight over this period: {0} → {1}. Bodyweight and assisted exercises count your body weight as part of the load.": "تغییرات وزن بدن در این بازه: {0} → {1}. در تمرینات با وزن بدن و حرکات کمکی، وزن شما به عنوان بخشی از وزنه محاسبه می‌شود.",
  "Weight stack": "وزنه‌های دستگاه",
  "The weights this machine really has, odd steps and all. Progression, deloads, warm-ups and the + and − buttons land only on these.": "وزن‌های واقعی این دستگاه، با هر فاصله‌ای بین آن‌ها. افزایش وزنه، کاهش بار، گرم‌کردن و دکمه‌های + و − فقط از این وزن‌ها استفاده می‌کنند.",
  "No list yet, so this exercise steps by its increment as usual.": "هنوز فهرستی وجود ندارد؛ وزنه این حرکت طبق معمول با گام افزایش تعیین‌شده تغییر می‌کند.",
  "First ({0})": "اول ({0})",
  "How many": "چند",
  "Fill in": "پر کنید",
  "That’s the whole stack: {0} {1} is the heaviest it goes, so the weight stays.": "به آخرین وزنه دستگاه رسیده‌اید: حداکثر {0} {1} است، پس وزنه تغییر نمی‌کند.",
  "No code on your phone? It only has one while it’s connected to this server: Settings → Account → Connect to my server.": "کدی در گوشی شما وجود ندارد؟ زمانی که به این سرور متصل است فقط یک مورد دارد: تنظیمات → حساب → اتصال به سرور من.",
  "Signing in on your computer too needs your own server. Connect this phone to it, and Add another device then gives the computer a code.": "ورود روی رایانه نیز به سرور شخصی نیاز دارد. این گوشی را به سرور متصل کنید؛ سپس با انتخاب «افزودن دستگاه دیگر»، کدی برای ورود رایانه دریافت کنید.",
  "How hard it felt": "چقدر سخت بود",
  "Not rated yet": "شدت هنوز ثبت نشده",
  "How hard did that feel?": "چقدر این احساس سخت بود؟",
  "Tap how it felt, or type an exact {0}.": "روی احساس آن ضربه بزنید یا یک {0} دقیق تایپ کنید.",
  "All out, nothing left": "حداکثر تلاش، بدون توان ادامه",
  "Nearly all out": "نزدیک حداکثر تلاش",
  "Very hard, one word at a time": "بسیار سخت؛ صحبت فقط کلمه‌به‌کلمه",
  "Hard, short sentences only": "سخت؛ فقط جمله‌های کوتاه",
  "Working, but steady": "فعال، اما با ریتم ثابت",
  "Easy, you could chat the whole way": "آسان؛ می‌توانید در تمام مدت صحبت کنید",
  "I own no dumbbells": "من دمبل ندارم",
  "Dumbbell lifts stay out of the library, the picker and the Coach’s plans.": "تمرینات دمبل در کتابخانه، فهرست انتخاب تمرین و برنامه‌های مربی نمایش داده نمی‌شوند.",
  "Everything but dumbbells": "همه چیز به جز دمبل",
  "None, so dumbbell lifts stay hidden.": "هیچ‌کدام؛ بنابراین تمرینات دمبل پنهان می‌مانند.",
  "openGym reads only while it is open: heart rate for workouts of the last day, weigh-ins of the last year. Older workouts stay as they are.": "openGym فقط هنگام باز بودن، ضربان قلب جلسه‌های روز گذشته و وزن‌کشی‌های سال گذشته را می‌خواند. جلسه‌های قدیمی بدون تغییر می‌مانند.",
  "Also during workouts": "همچنین در طول تمرین",
  "A cobweb in the header, bats behind the rest timer, pumpkins on the finish screen. Never on your sets.": "یک تار عنکبوت در هدر، خفاش‌ها پشت تایمر استراحت، کدو تنبل روی صفحه پایان. هرگز در ست‌های خود.",
  "Seasonal themes": "تم‌های فصلی",
  "Little extras for the time of year.": "جزئیات کوچک متناسب با فصل.",
