  'Delete programme': 'حذف دوره تمرینی',
  'Deload week': 'هفته کاهش بار',
  'Each adds its own routines, so your plan stays as it is until you start it.': 'هر کدام روتین‌های خودش را اضافه می‌کند، پس برنامه شما تا وقتی شروعش نکنید همان‌طور می‌ماند.',
  'Effort for the week': 'شدت تلاش برای این هفته',
  'Empty leaves the weight to your progression. A %1RM is worked out from your best estimated 1RM.': 'اگر خالی بماند، وزنه را پیشرفت شما تعیین می‌کند. %1RM از بهترین 1RM تخمینی شما محاسبه می‌شود.',
  'End programme': 'پایان دوره تمرینی',
  'End “{0}”?': '«{0}» تمام شود؟',
  'Four days. Your progression picks the weights, the effort climbs to RPE 9, then a deload.': 'چهار روز. پیشرفت شما وزنه‌ها را انتخاب می‌کند، شدت تا RPE 9 بالا می‌رود، بعد کاهش بار.',
  'Heavier means every %1RM goes up {0} points.': 'سنگین‌تر یعنی هر %1RM به اندازه {0} واحد بالا می‌رود.',
  'It is running: ending it brings your plan back. Its routines stay.': 'در حال اجراست: تمام کردنش برنامه شما را برمی‌گرداند. روتین‌هایش می‌مانند.',
  'Its routines stay.': 'روتین‌هایش می‌مانند.',
  'Its schedule takes over your plan until you end it. Then your plan comes back as it was.': 'تا وقتی تمامش نکنید، زمان‌بندی‌اش جای برنامه شما را می‌گیرد. بعد برنامه شما همان‌طور که بود برمی‌گردد.',
  'Lighter weights, and its sessions do not count toward progression.': 'وزنه‌های سبک‌تر، و جلسه‌هایش در پیشرفت حساب نمی‌شوند.',
  'Linear 5×5 style, 12 weeks': 'سبک خطی 5×5، ۱۲ هفته',
