  'No schedule yet. Put routines on your week or in a loop in Plan, then take it over here.': 'هنوز زمان‌بندی ندارید. در صفحه برنامه روتین‌ها را در هفته یا در یک چرخه بگذارید، بعد اینجا آن را بردارید.',
