  'For gyms that mix kg and lb. This exercise is shown and typed in it everywhere, plates and steps included. Totals in Stats stay in {0}.': 'برای باشگاه‌هایی که kg و lb را قاطی دارند. این تمرین همه‌جا با همین واحد نمایش داده و وارد می‌شود، از جمله صفحه‌ها و گام‌ها. مجموع‌ها در آمار به {0} می‌مانند.',
