  'Finish saves the session and moves your weights along. This practice one just quietly disappears.': '«پایان» جلسه را ذخیره می‌کند و وزنه‌هایتان را جلو می‌برد. این جلسه آزمایشی بی‌سروصدا ناپدید می‌شود.',
  'Finish the tour?': 'گشت را تمام کنید؟',
