  'We swapped in a practice copy with a pretend workout and weigh-in. Poke at anything, nothing here sticks.': 'یک نسخه آزمایشی با یک تمرین و وزن‌کشی ساختگی جایگزین کردیم. به هر چیزی دست بزنید، اینجا هیچ چیزی ماندگار نیست.',
