  'Where your data goes in and out. We only point, nothing runs until you tap it yourself.': 'جایی که داده‌هایتان وارد و خارج می‌شوند. ما فقط اشاره می‌کنیم، تا خودتان نزنید چیزی اجرا نمی‌شود.',
  'Workouts, weigh-ins and what can be fixed': 'تمرینات، وزن‌کشی‌ها و چیزهایی که می‌شود اصلاح کرد',
