  'You feel strong, so a little more on the bar for what is left. Not a new max, just a nudge.': 'حس قدرت دارید، پس برای باقی‌مانده کمی وزنه بیشتر روی میله. رکورد جدید نه، فقط یک تلنگر.',
  'Your rows, as a share of the work weight, so they grow with it.': 'ردیف‌های شما، به صورت درصدی از وزنه اصلی، پس همراه آن بزرگ می‌شوند.',
